  milestone?: IssueEventMilestone;
  project_card?: IssueEventProjectCard;
  rename?: IssueEventRename;
  issue_type?: IssueTypeWebhook;
  prev_issue_type?: IssueTypeWebhook;
  sub_issue?: NullableIssueReference;
  parent_issue?: NullableIssueReference;
  blocked_by?: NullableIssueReference;
  blocking?: NullableIssueReference;
  author_association?: AuthorAssociation;
  lock_reason?: string | null;
